:root{--bg:#1e1e1e;--side:#252526;--fg:#cccccc;--muted:#9d9d9d;--border:#3c3c3c;--link:#3794ff;--hover:#2a2d2e;--card:#252526;--sel:#04395e}
*{box-sizing:border-box} body,.wrap{font-family:-apple-system,'Segoe UI',sans-serif;font-size:13px;color:var(--fg);background:var(--bg)}
.wrap{display:flex;min-height:620px}
.side{width:240px;background:var(--side);border-right:1px solid var(--border);padding:6px 0}
.side h4{font-size:11px;letter-spacing:.06em;color:var(--muted);margin:6px 12px;text-transform:uppercase}
.nav{display:flex;gap:6px;align-items:center;padding:3px 20px;cursor:pointer;color:var(--fg);background:none;border:0;width:100%;text-align:left;font:inherit}
.nav:hover{background:var(--hover)} .nav.sel{background:var(--sel);outline:1px solid #007fd4}
.main{flex:1;padding:16px 24px;max-width:900px}
h1{font-size:20px;margin:4px 0 12px;font-weight:600}
.summary-card{border:1px solid var(--border);background:var(--card);border-radius:4px;padding:12px 14px;margin-bottom:18px}
.summary-label{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin:8px 0 2px}
.summary-label:first-child{margin-top:0} .summary-value{line-height:1.5}
.chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}
.chip{border:1px solid var(--border);border-radius:10px;padding:1px 8px;font-size:12px}
.folder{font-size:12px;color:var(--muted);margin:18px 0 4px;border-bottom:1px solid var(--border);padding-bottom:4px}
.group-header{display:flex;align-items:center;gap:6px;background:none;border:0;color:var(--fg);font:inherit;font-weight:600;padding:6px 0;cursor:pointer;width:100%;text-align:left}
.group-header::before{content:'▾';color:var(--muted)} .count{color:var(--muted);font-weight:400}
.list{list-style:none;margin:0 0 6px;padding:0}
.trow{display:flex;justify-content:space-between;padding:4px 8px 4px 18px;border-radius:3px}
.trow:hover{background:var(--hover)}
.trow-title{color:var(--link);background:none;border:0;font:inherit;cursor:pointer;padding:0}
.trow-description{color:var(--muted);font-size:12px}
.rd-crumbs{font-size:12px;color:var(--muted);margin-bottom:6px} .rd-crumbs a{color:var(--link);text-decoration:none;cursor:pointer}
.rd-summary{border-left:3px solid #007fd4;background:var(--card);padding:8px 12px;margin:10px 0 16px}
.rd-summary-label{font-size:11px;text-transform:uppercase;color:var(--muted)}
.body h2{font-size:16px;border-bottom:1px solid var(--border);padding-bottom:4px} .body a{color:var(--link)}
.body code{background:#2d2d2d;padding:0 4px;border-radius:3px}
.empty{padding:24px;border:1px dashed var(--border);border-radius:4px;color:var(--muted)} .empty code{color:var(--fg)}

